/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type ComputerActionKind = "click" | "type" | "scroll" | "navigate" | "key" | "wait" | "drag"

export interface ComputerAction {
  kind: ComputerActionKind
  /** What the agent does, as a short verb phrase: "Click Sign in", "Type dev@harborgoods.co". */
  label: string
  /** Point on the screen, 0 to 1 from the top left. The cursor glides there. */
  x?: number
  y?: number
}

export interface ComputerFrame {
  id: string
  /** Address shown in the bar. */
  url?: string
  /** What the screen shows: an `<img>`, a canvas, or HTML. Size it to fill its box. */
  screen: React.ReactNode
  /** Smaller stand-in for the thumbnail strip. Defaults to `screen`. */
  thumbnail?: React.ReactNode
  /** The action taken on this frame. Drives the cursor, the label and the click ring. */
  action?: ComputerAction
  /** Ms since the session started. Places the frame on the timeline. */
  at?: number
}

/**
 * - `connecting`: no picture yet.
 * - `live`: the agent drives and frames arrive.
 * - `paused`: the agent waits for you, usually at a sign-in or a hard block.
 * - `user`: you drive. Frames stop; the agent's cursor hides.
 * - `ended`: the run finished. The timeline replays it.
 * - `error`: the connection dropped.
 */
export type ComputerViewStatus = "connecting" | "live" | "paused" | "user" | "ended" | "error"

export interface ComputerViewProps extends Omit<React.ComponentProps<"section">, "title"> {
  frames: ComputerFrame[]
  status: ComputerViewStatus
  /** Accessible name. Default "Agent browser". */
  label?: string
  /** Why the agent paused, shown over the screen in `paused`. */
  pausedReason?: React.ReactNode
  /** Error details and how to fix it, shown in `error`. */
  errorText?: React.ReactNode
  onTakeOver?: () => void
  onHandBack?: () => void
  onReconnect?: () => void
  /** Controlled playhead. */
  index?: number
  defaultIndex?: number
  onIndexChange?: (index: number) => void
  /** How long replay holds each frame, in ms. Default 1400. */
  frameDurationMs?: number
  /** Show the replay controls, timeline and thumbnails. Default true. */
  showScrubber?: boolean
  /** Show the thumbnail strip under the timeline. Default true. */
  showThumbnails?: boolean
  /** Screen aspect ratio. Default 16 / 10. */
  aspectRatio?: number
  /** Replace the screen with your own element, such as a live `<iframe>`. */
  children?: React.ReactNode
}

/**
 * Playhead for a recorded or live agent session: a list of frames (screenshots, steps) and the
 * one on screen.
 *
 * - Live: the playhead follows the newest frame as frames arrive. Seeking back stops following;
 *   `goLive()`, or playing up to the newest frame, follows again.
 * - Replay: `play()` steps through frames, holding each for its duration, and stops on the last.
 *   Playing from the last frame starts over.
 * - Controlled (`index` plus `onIndexChange`) or uncontrolled (`defaultIndex`).
 */

interface UseChatcnRunReplayOptions {
  /** Number of frames so far. */
  count: number
  /** The session is still running and new frames may arrive. */
  live?: boolean
  /** How long playback holds each frame, in ms. A number, or one per frame. Default 1400. */
  durationMs?: number | ((index: number) => number)
  index?: number
  defaultIndex?: number
  onIndexChange?: (index: number) => void
}

interface ChatcnRunReplay {
  index: number
  playing: boolean
  /** Live and showing the newest frame. */
  following: boolean
  atStart: boolean
  atEnd: boolean
  play: () => void
  pause: () => void
  toggle: () => void
  seek: (index: number) => void
  next: () => void
  prev: () => void
  /** Jump to the newest frame and follow again. */
  goLive: () => void
}

const clamp = (value: number, count: number) => Math.max(0, Math.min(count - 1, value))

function useChatcnRunReplay({
  count,
  live = false,
  durationMs = 1400,
  index: indexProp,
  defaultIndex,
  onIndexChange,
}: UseChatcnRunReplayOptions): ChatcnRunReplay {
  const last = Math.max(0, count - 1)
  const [indexState, setIndexState] = React.useState(defaultIndex ?? (live ? last : 0))
  const [following, setFollowing] = React.useState(live)
  const [playing, setPlaying] = React.useState(false)
  const raw = indexProp ?? indexState
  const index = count === 0 ? 0 : clamp(raw, count)

  const onChange = React.useRef(onIndexChange)
  onChange.current = onIndexChange
  const set = React.useCallback(
    (next: number) => {
      if (indexProp === undefined) setIndexState(next)
      onChange.current?.(next)
    },
    [indexProp],
  )

  // Following: new frames move the playhead with them.
  React.useEffect(() => {
    if (live && following && count > 0 && index !== last) set(last)
  }, [live, following, count, index, last, set])

  // A session that ends stops following, so the replay opens on the last frame it showed. One that
  // comes back (a reconnect after an error) follows the newest frame again.
  React.useEffect(() => {
    setFollowing(live)
  }, [live])

  const durationFor = React.useRef(durationMs)
  durationFor.current = durationMs

  React.useEffect(() => {
    if (!playing) return
    if (index >= last) {
      setPlaying(false)
      if (live) setFollowing(true)
      return
    }
    const d = durationFor.current
    const wait = typeof d === "function" ? d(index) : d
    const id = window.setTimeout(() => set(index + 1), wait)
    return () => window.clearTimeout(id)
  }, [playing, index, last, live, set])

  const seek = React.useCallback(
    (next: number) => {
      const target = clamp(next, count)
      set(target)
      if (live) setFollowing(target === last)
    },
    [count, last, live, set],
  )

  const play = React.useCallback(() => {
    if (count < 2) return
    if (index >= last) {
      set(0)
      if (live) setFollowing(false)
    }
    setPlaying(true)
  }, [count, index, last, live, set])

  const pause = React.useCallback(() => setPlaying(false), [])
  // Stable callbacks, so memoized thumbnails and controls do not re-render on every frame.
  const toggle = React.useCallback(() => (playing ? pause() : play()), [playing, pause, play])
  const seekStop = React.useCallback(
    (next: number) => {
      setPlaying(false)
      seek(next)
    },
    [seek],
  )
  const next = React.useCallback(() => seekStop(index + 1), [seekStop, index])
  const prev = React.useCallback(() => seekStop(index - 1), [seekStop, index])
  const goLive = React.useCallback(() => {
    setPlaying(false)
    setFollowing(true)
    set(last)
  }, [set, last])

  return {
    index,
    playing,
    following: live && following,
    atStart: index === 0,
    atEnd: index >= last,
    play,
    pause,
    toggle,
    seek: seekStop,
    next,
    prev,
    goLive,
  }
}

/** The last known pointer position at or before `index`, so the cursor rests between actions. */
function pointAt(frames: ComputerFrame[], index: number) {
  for (let i = index; i >= 0; i--) {
    const a = frames[i]?.action
    if (a && a.x !== undefined && a.y !== undefined) return { x: a.x, y: a.y }
  }
  return undefined
}

function reducedMotion() {
  return (
    typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

