/* -------------------------------------------------------------------------------------------------
 * Screen layers
 * -----------------------------------------------------------------------------------------------*/

/** Box that scales its content: screens sized in `cqw` units shrink cleanly into thumbnails. */
function ScreenBox({
  children,
  className,
  style,
}: {
  children: React.ReactNode
  className?: string
  style?: React.CSSProperties
}) {
  return (
    <div
      className={cn(
        "bg-(color:--chatcn-bg) [container-type:size] absolute inset-0 overflow-hidden",
        className,
      )}
      style={style}
    >
      {children}
    </div>
  )
}

