    case "click":
      return <MousePointer2Icon />
    case "type":
      return <KeyboardIcon />
    case "scroll":
      return <ArrowDownIcon />
    case "navigate":
      return <GlobeIcon />
    case "key":
      return <CommandIcon />
    case "wait":
      return <HourglassIcon />
    case "drag":
      return <MoveIcon />
  }
}

