/* -------------------------------------------------------------------------------------------------
 * Timeline
 * -----------------------------------------------------------------------------------------------*/

function Timeline({
  frames,
  index,
  playing,
  onSeek,
  onToggle,
}: {
  frames: ComputerFrame[]
  index: number
  playing: boolean
  onSeek: (index: number) => void
  onToggle: () => void
}) {
  const track = React.useRef<HTMLDivElement>(null)
  const [dragging, setDragging] = React.useState(false)
  const [hover, setHover] = React.useState<number>()
  const count = frames.length
  const total = frames[count - 1]?.at
  const timed = total !== undefined && total > 0 && frames.every((f) => f.at !== undefined)
  const pos = (i: number) =>
    count < 2 ? 0 : timed ? (frames[i]?.at ?? 0) / (total as number) : i / (count - 1)

  const nearest = (clientX: number) => {
    const rect = track.current?.getBoundingClientRect()
    if (!rect || count === 0) return 0
    const rtl = getComputedStyle(track.current as HTMLElement).direction === "rtl"
    let p = (clientX - rect.left) / rect.width
    if (rtl) p = 1 - p
    let best = 0
    let dist = Number.POSITIVE_INFINITY
    for (let i = 0; i < count; i++) {
      const d = Math.abs(pos(i) - p)
      if (d < dist) {
        dist = d
        best = i
      }
    }
    return best
  }

  const current = frames[index]
  const p = pos(index)

  return (
    <div
      ref={track}
      role="slider"
      tabIndex={0}
      aria-label="Replay position"
      aria-valuemin={1}
      aria-valuemax={Math.max(1, count)}
      aria-valuenow={index + 1}
      aria-valuetext={`Step ${index + 1} of ${count}${current?.action ? `: ${current.action.label}` : ""}`}
      data-slot="computer-view-timeline"
      onKeyDown={(event) => {
        const map: Record<string, number> = {
          ArrowRight: index + 1,
          ArrowUp: index + 1,
          ArrowLeft: index - 1,
          ArrowDown: index - 1,
          Home: 0,
          End: count - 1,
          PageUp: index + 5,
          PageDown: index - 5,
        }
        if (event.key === " " || event.key === "k") {
          event.preventDefault()
          onToggle()
          return
        }
        let target = map[event.key]
        if (target === undefined) return
        const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
        if (rtl && (event.key === "ArrowRight" || event.key === "ArrowLeft"))
          target = event.key === "ArrowRight" ? index - 1 : index + 1
        event.preventDefault()
        onSeek(Math.max(0, Math.min(count - 1, target)))
      }}
      onPointerDown={(event) => {
        if (event.button !== 0) return
        event.currentTarget.setPointerCapture(event.pointerId)
        setDragging(true)
        onSeek(nearest(event.clientX))
      }}
      onPointerMove={(event) => {
        if (event.pointerType === "mouse") setHover(nearest(event.clientX))
        if (dragging) onSeek(nearest(event.clientX))
      }}
      onPointerUp={() => setDragging(false)}
      onPointerCancel={() => setDragging(false)}
      onPointerLeave={() => setHover(undefined)}
      className={cn(
        "group/timeline rounded-(--chatcn-radius-sm) relative h-8 cursor-pointer touch-none outline-none select-none",
        "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:outline-offset-2",
        "pointer-coarse:h-11",
      )}
    >
      {/* Track and fill */}
      <div className="absolute inset-x-0 top-1/2 h-0.5 -translate-y-1/2 overflow-hidden rounded-full">
        <div className="bg-(color:--chatcn-alpha-400) absolute inset-0" />
        <div
          className={cn(
            "bg-(color:--chatcn-accent) absolute inset-0 origin-left rtl:origin-right",
            !dragging && !playing && "ease-(--chatcn-ease-out) transition-transform duration-200",
            playing && "ease-(--chatcn-ease-out) transition-transform duration-300",
            "motion-reduce:transition-none",
          )}
          style={{ transform: `scaleX(${p})` }}
        />
      </div>

      {/* One tick per frame. Past ticks are ink, future ticks are faint. */}
      {frames.map((frame, i) => (
        <span
          key={frame.id}
          aria-hidden="true"
          className={cn(
            "absolute top-1/2 h-2 w-px -translate-x-1/2 -translate-y-1/2 rtl:translate-x-1/2",
            i <= index ? "bg-(color:--chatcn-fg)" : "bg-(color:--chatcn-fg-faint)",
            i === hover && i !== index && "bg-(color:--chatcn-fg) h-3",
          )}
          style={{ insetInlineStart: `${pos(i) * 100}%` }}
        />
      ))}

      {/* Playhead: a 2 px bar riding a full-width layer, so it moves by transform alone. */}
      <div
        aria-hidden="true"
        className={cn(
          "pointer-events-none absolute inset-0 [--chatcn-dir:1] rtl:[--chatcn-dir:-1]",
          !dragging && "ease-(--chatcn-ease-out) transition-transform duration-200",
          playing && "duration-300",
          "motion-reduce:transition-none",
        )}
        style={{ transform: `translateX(calc(${p} * 100% * var(--chatcn-dir, 1)))` }}
      >
        <span className="bg-(color:--chatcn-fg) ring-(color:--chatcn-card) absolute start-0 top-1/2 h-4 w-0.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2 rtl:translate-x-1/2" />
      </div>

      {/* Hover label: which step is under the pointer. */}
      {hover !== undefined && !dragging && frames[hover] ? (
        <span
          aria-hidden="true"
          className="bg-(color:--chatcn-fg) text-(color:--chatcn-bg) text-[0.75rem]/[1rem] rounded-(--chatcn-radius-sm) shadow-(--chatcn-shadow-md) pointer-events-none absolute bottom-full z-10 mb-1 flex h-6 -translate-x-1/2 items-center gap-1.5 px-2 font-medium whitespace-nowrap rtl:translate-x-1/2"
          style={{ insetInlineStart: `${pos(hover) * 100}%` }}
        >
          <span className="tabular-nums opacity-60">{hover + 1}</span>
          {frames[hover]?.action?.label ?? frames[hover]?.url ?? "Frame"}
        </span>
      ) : null}
    </div>
  )
}

