/**
 * The agent's screen: a live view with a cursor that glides to each action point, a label for
 * what it is doing ("Click Sign in"), a click ring, take over and hand back, and after the run a
 * replay scrubber with a timeline and step thumbnails. Works with any list of frames: real
 * screenshots, an `<iframe>` through `children`, or scripted HTML screens.
 */
export function ComputerView({
  frames,
  status,
  label = "Agent browser",
  pausedReason,
  errorText,
  onTakeOver,
  onHandBack,
  onReconnect,
  index: indexProp,
  defaultIndex,
  onIndexChange,
  frameDurationMs = 1400,
  showScrubber = true,
  showThumbnails = true,
  aspectRatio = 16 / 10,
  children,
  className,
  ...props
}: ComputerViewProps) {
  const live =
    status === "live" || status === "paused" || status === "user" || status === "connecting"
  const replay = useChatcnRunReplay({
    count: frames.length,
    live,
    durationMs: frameDurationMs,
    index: indexProp,
    defaultIndex,
    onIndexChange,
  })
  const { index } = replay
  const frame = frames[index]
  const point = pointAt(frames, index)

  // Crossfade: the previous frame stays underneath while the new one fades in over it. Derived
  // during render, so the frame underneath is always the one that was just on screen.
  const [shown, setShown] = React.useState<{ cur?: string; prev?: string }>({ cur: frame?.id })
  if (frame?.id !== shown.cur) setShown({ cur: frame?.id, prev: shown.cur })
  const prev = frames.find((f) => f.id === shown.prev)

  // Keep the selected thumbnail in view without scrolling the page.
  const strip = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    const el = strip.current
    const thumb = el?.querySelector<HTMLElement>("[data-slot=computer-view-thumb][data-selected]")
    if (!el || !thumb) return
    const left = thumb.offsetLeft - el.offsetLeft
    const right = left + thumb.offsetWidth
    if (left < el.scrollLeft || right > el.scrollLeft + el.clientWidth) {
      el.scrollTo({
        left: left - el.clientWidth / 2 + thumb.offsetWidth / 2,
        behavior: reducedMotion() ? "auto" : "smooth",
      })
    }
  }, [index])

  const scrubberShown = showScrubber && frames.length > 0
  const select = React.useCallback((i: number) => replay.seek(i), [replay.seek])
  const total = frames[frames.length - 1]?.at
  const viewingPast = live && !replay.following && frames.length > 0
  const cursorVisible = status !== "user" && status !== "connecting" && status !== "error"
  const statusText =
    status === "connecting"
      ? "Connecting"
      : status === "live"
        ? viewingPast
          ? "Viewing earlier step"
          : "Live"
        : status === "paused"
          ? "Waiting for you"
          : status === "user"
            ? "You are in control"
            : status === "ended"
              ? "Replay"
              : "Disconnected"

  return (
    <section
      aria-label={label}
      data-slot="computer-view"
      data-status={status}
      className={cn(
        "rounded-(--chatcn-radius-xl) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-md) flex min-w-0 flex-col overflow-hidden",
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      {/* Address bar */}
      <div className="flex h-11 min-w-0 items-center gap-2 px-2">
        <div className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) flex h-7 min-w-0 flex-1 items-center gap-2 px-2.5">
          <LockIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-3.5 shrink-0" />
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) grid min-w-0 flex-1 font-mono">
            <span
              key={frame?.url ?? "blank"}
              className="col-start-1 row-start-1 flex min-w-0 transition-opacity duration-150 starting:opacity-0"
            >
              {frame?.url ? (
                <Address url={frame.url} />
              ) : (
                <span className="truncate">
                  {status === "connecting" ? "Starting the browser…" : "about:blank"}
                </span>
              )}
            </span>
          </span>
        </div>
        <span
          className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) flex shrink-0 items-center gap-1.5 px-1.5 font-medium"
          aria-live="polite"
        >
          {status === "live" && !viewingPast ? (
            <span aria-hidden="true" className="bg-(color:--chatcn-fg) size-1.5 rounded-full" />
          ) : status === "connecting" ? (
            <Spinner />
          ) : null}
          <span className="max-sm:sr-only">{statusText}</span>
        </span>
        {viewingPast ? (
          <Button size="xs" variant="subtle" onClick={replay.goLive}>
            Back to live
          </Button>
        ) : null}
        {(status === "live" || status === "paused") && onTakeOver ? (
          <Button
            size="sm"
            variant={status === "paused" ? "solid" : "outline"}
            onClick={onTakeOver}
            className="pointer-coarse:h-11"
          >
            <HandIcon />
            Take over
          </Button>
        ) : status === "user" && onHandBack ? (
          <Button size="sm" variant="solid" onClick={onHandBack} className="pointer-coarse:h-11">
            <ComputerUseIcon />
            Hand back
          </Button>
        ) : null}
      </div>

      {/* Screen */}
      <div
        data-slot="computer-view-screen"
        className="bg-(color:--chatcn-inset) [container-type:size] relative w-full overflow-hidden"
        style={{ aspectRatio }}
      >
        {children ? (
          <div className="absolute inset-0">{children}</div>
        ) : (
          <>
            {prev && prev.id !== frame?.id ? (
              <ScreenBox key={`prev-${prev.id}`}>{prev.screen}</ScreenBox>
            ) : null}
            {frame ? (
              <ScreenBox
                key={frame.id}
                className="ease-(--chatcn-ease-out) transition-opacity duration-200 starting:opacity-0"
              >
                {frame.screen}
              </ScreenBox>
            ) : null}
          </>
        )}

        <Pointer frame={frame} point={point} visible={cursorVisible} />

        {/* User in control: an inset ink ring, and the agent's cursor is gone. */}
        <div
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute inset-0 z-20 shadow-[inset_0_0_0_2px_var(--chatcn-fg)]",
            "transition-opacity duration-200",
            // Last row of the frame: follow its bottom corners so the ring is not clipped.
            !scrubberShown && "rounded-b-(--chatcn-radius-xl)",
            status === "user" ? "opacity-100" : "opacity-0",
          )}
        />
        {status === "user" ? (
          <div className="pointer-events-none absolute inset-x-0 top-3 z-20 flex justify-center">
            <span className="bg-(color:--chatcn-fg) text-(color:--chatcn-bg) text-[0.75rem]/[1rem] shadow-(--chatcn-shadow-md) flex h-7 items-center gap-1.5 rounded-full px-3 font-medium transition-opacity duration-200 starting:opacity-0">
              <MousePointer2Icon aria-hidden="true" className="size-3.5" />
              You are in control. Screenshots are paused.
            </span>
          </div>
        ) : null}

        {status === "paused" ? (
          <div className="absolute inset-0 z-20 flex items-end justify-center p-4 transition-opacity duration-200 starting:opacity-0">
            <div className="bg-(color:--chatcn-bg)/55 absolute inset-0" aria-hidden="true" />
            <div className="bg-(color:--chatcn-surface) shadow-(--chatcn-shadow-lg) rounded-(--chatcn-radius-lg) relative flex max-w-sm items-start gap-3 p-4">
              <PauseIcon aria-hidden="true" className="text-(color:--chatcn-fg) mt-0.5 size-4 shrink-0" />
              <div className="flex min-w-0 flex-col gap-3">
                <div className="flex flex-col gap-0.5">
                  <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] font-medium">The agent needs you</p>
                  <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">
                    {pausedReason ??
                      "Take over to finish this step. The agent waits until you hand back."}
                  </p>
                </div>
                {onTakeOver ? (
                  <div>
                    <Button size="sm" variant="solid" onClick={onTakeOver}>
                      <HandIcon />
                      Take over
                    </Button>
                  </div>
                ) : null}
              </div>
            </div>
          </div>
        ) : null}

        {status === "connecting" && frames.length === 0 ? (
          <div className="text-(color:--chatcn-fg-subtle) text-[0.8125rem]/[1.25rem] absolute inset-0 flex flex-col items-center justify-center gap-2.5">
            <Spinner className="size-4" />
            Connecting to the browser…
          </div>
        ) : null}

        {status === "error" ? (
          <div className="bg-(color:--chatcn-inset)/90 absolute inset-0 z-20 flex flex-col items-center justify-center gap-1 p-6 text-center">
            <CircleXIcon aria-hidden="true" className="text-(color:--chatcn-red) mb-2 size-5" />
            <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] font-medium">Lost the connection to the browser</p>
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) max-w-80 text-pretty">
              {errorText ?? "Check that the sandbox is still running, then reconnect."}
            </p>
            {onReconnect ? (
              <Button size="sm" variant="outline" onClick={onReconnect} className="mt-3">
                Reconnect
              </Button>
            ) : null}
          </div>
        ) : null}
      </div>

      {/* Scrubber */}
      {scrubberShown ? (
        <div className="border-(color:--chatcn-border)/70 flex flex-col gap-1 border-t px-2 pt-1.5 pb-2.5">
          <div className="flex min-w-0 items-center gap-0.5">
            <Button
              size="icon-sm"
              aria-label={replay.playing ? "Pause replay" : "Play replay"}
              disabled={frames.length < 2 || status === "user"}
              onClick={replay.toggle}
              className="relative pointer-coarse:size-11"
            >
              <PauseIcon
                className={cn(
                  "ease-(--chatcn-ease-out) absolute transition-[opacity,scale,filter] duration-150",
                  replay.playing ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
                )}
              />
              <PlayIcon
                className={cn(
                  "ease-(--chatcn-ease-out) absolute transition-[opacity,scale,filter] duration-150",
                  replay.playing ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
                )}
              />
            </Button>
            <Button
              size="icon-sm"
              aria-label="Previous step"
              disabled={replay.atStart}
              onClick={replay.prev}
              className="pointer-coarse:size-11"
            >
              <SkipBackIcon className="rtl:-scale-x-100" />
            </Button>
            <Button
              size="icon-sm"
              aria-label="Next step"
              disabled={replay.atEnd}
              onClick={replay.next}
              className="pointer-coarse:size-11"
            >
              <SkipForwardIcon className="rtl:-scale-x-100" />
            </Button>
            <p className="text-[0.8125rem]/[1.25rem] ms-1.5 flex min-w-0 flex-1 items-baseline gap-2">
              <span className="text-(color:--chatcn-fg) shrink-0 font-medium tabular-nums">
                Step {index + 1}
                <span className="text-(color:--chatcn-fg-subtle) font-normal"> of {frames.length}</span>
              </span>
              {frame?.action ? (
                <span className="text-(color:--chatcn-fg-muted) truncate">{frame.action.label}</span>
              ) : null}
            </p>
            {total !== undefined && frame?.at !== undefined ? (
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 pe-1.5 tabular-nums">
                {clock(frame.at)} / {clock(total)}
              </span>
            ) : null}
          </div>
          <div className="px-2">
            <Timeline
              frames={frames}
              index={index}
              playing={replay.playing}
              onSeek={replay.seek}
              onToggle={replay.toggle}
            />
          </div>
          {showThumbnails ? (
            <div
              ref={strip}
              data-slot="computer-view-thumbs"
              className="chatcn-scroll -mx-0.5 flex gap-1.5 overflow-x-auto px-1.5 pt-1 pb-0.5"
            >
              {frames.map((f, i) => (
                <Thumb key={f.id} frame={f} index={i} selected={i === index} onSelect={select} />
              ))}
            </div>
          ) : null}
        </div>
      ) : null}
    </section>
  )
}

export default ComputerView

