}

export default function ComputerViewDemo() {
  const [run, setRun] = React.useState(0)
  const [phase, setPhase] = React.useState<Phase>("before")
  const [count, setCount] = React.useState(OPENING)

  // The scripted session. Frames arrive one at a time; the password step waits for a person.
  React.useEffect(() => {
    let id: number
    const later = (fn: () => void, ms: number) => {
      id = window.setTimeout(fn, ms)
    }
    if (phase === "before") {
      if (count < BEFORE_PASSWORD.length) later(() => setCount((c) => c + 1), TICK)
      else later(() => setPhase("paused"), 600)
    } else if (phase === "paused") later(() => setPhase("user"), PAUSED_MS)
    else if (phase === "user") later(() => setPhase("after"), USER_MS)
    else if (phase === "after") {
      const total = BEFORE_PASSWORD.length + AFTER_PASSWORD.length
      if (count < total) later(() => setCount((c) => c + 1), TICK)
      else later(() => setPhase("ended"), 900)
    } else {
      later(() => {
        setCount(OPENING)
        setPhase("before")
        setRun((r) => r + 1)
      }, 2600)
    }
    return () => window.clearTimeout(id)
  }, [phase, count, run])

  const before = stamp(BEFORE_PASSWORD, 0)
  // The pause adds real time to the run, so later frames sit further along the timeline.
  const after = stamp(AFTER_PASSWORD, BEFORE_PASSWORD.length * STEP_MS + 9000)
  const all = [...before, ...after]
  const frames = all.slice(0, count)
  // While you type the password, the last frame shows the field filling, screenshots paused.
  const shown =
    phase === "user" || phase === "after"
      ? frames.map((f) => (f.id === "password" ? { ...f, screen: <PasswordScreen filled /> } : f))
      : frames

  const status: ComputerViewStatus =
    phase === "paused" ? "paused" : phase === "user" ? "user" : phase === "ended" ? "ended" : "live"

  return (
    <FitFrame>
      <div className="flex w-full flex-col items-center gap-4 p-6">
        <div className="flex w-full max-w-2xl flex-col">
          <ComputerView
            key={run}
            frames={shown}
            status={status}
            pausedReason="The password is next. Enter it yourself; the agent never sees what you type."
            // A click on Take over (the recorder's cursor wanders) still hands back on its own.
            onTakeOver={() => setPhase("user")}
            onHandBack={() => setPhase("after")}
          />
        </div>
        <MoreOn slug="computer-view">
          Screenshots, steps and a timeline you can scrub. Free on
        </MoreOn>
      </div>
    </FitFrame>
  )
}
